<script setup>
import AdminLayout from '../../AdminLayout.vue'
import { Link, router, useForm } from '@inertiajs/vue3'
defineOptions({ layout: AdminLayout })
const props = defineProps({ portal: Object, tab: String, info: Object, alerts: Array, supportEvents: Array, tableCount: Number, dbError: String, packages: Array, payments: Array, charges: Array, extras: Object, quotes: Object, summary: Object, logs: Object, ranges: Object })
const profile = useForm({ portal_name: props.portal.portal_name, portal_reg_no: props.portal.portal_reg_no || '', editor_name: props.portal.editor_name || '', editor_email: props.portal.editor_email || '', editor_mobile: props.portal.editor_mobile || '' })
const pay = useForm({ package_id: '', advance_months: 0, amount: '', method: 'cash', trx_id: '', note: '' })
const charge = useForm({ purpose: '', amount: '', type: 'one_time' })
function act(url, method='post', data={}) { router[method](url, data) }
</script>

<template>
  <div>
    <div class="d-flex flex-wrap justify-content-between align-items-center gap-3 mb-4"><div><Link href="/admin/portals" class="small">← All portals</Link><h3 class="mb-0 mt-2">{{ portal.portal_name }}</h3><span class="small text-body-tertiary">{{ portal.editor_mobile }} · {{ portal.database_name || 'no database' }}</span></div><div class="d-flex gap-2"><button class="btn btn-phoenix-secondary" @click="act(`/admin/portals/${portal.id}/support-session`)">Support login</button><button class="btn" :class="portal.status==='active'?'btn-phoenix-danger':'btn-phoenix-success'" @click="act(`/admin/portals/${portal.id}/toggle`)">{{ portal.status==='active'?'Suspend':'Activate' }}</button></div></div>
    <div v-if="alerts.length" class="alert alert-subtle-warning"><div v-for="a in alerts" :key="a.message">{{ a.message }}</div></div>
    <ul class="nav nav-tabs mb-4"><li v-for="name in ['overview','billing','activity']" :key="name" class="nav-item"><Link class="nav-link text-capitalize" :class="{active:tab===name}" :href="`/admin/portals/${portal.id}?tab=${name}`">{{ name }}</Link></li></ul>
    <template v-if="tab==='overview'">
      <div v-if="$page.props.new_api_token" class="alert alert-subtle-warning"><b>Copy this API token now:</b><code class="ms-2 user-select-all">{{ $page.props.new_api_token }}</code></div>
      <div class="row g-3"><div class="col-xl-7"><div class="card"><div class="card-header"><h5 class="mb-0">Portal details</h5></div><div class="card-body"><form @submit.prevent="profile.put(`/admin/portals/${portal.id}`)"><div v-for="[key,label] in [['portal_name','Portal name'],['portal_reg_no','Registration no.'],['editor_name','Editor name'],['editor_email','Editor email'],['editor_mobile','Mobile']]" :key="key" class="mb-3"><label class="form-label">{{ label }}</label><input v-model="profile[key]" class="form-control" :class="{'is-invalid':profile.errors[key]}"><div v-if="profile.errors[key]" class="invalid-feedback">{{ profile.errors[key] }}</div></div><button class="btn btn-primary">Save changes</button></form></div></div></div>
        <div class="col-xl-5"><div class="card mb-3"><div class="card-body"><h5>Tenant database</h5><dl class="row mb-3"><dt class="col-5">Database</dt><dd class="col-7">{{ portal.database_name || '—' }}</dd><dt class="col-5">Provisioned</dt><dd class="col-7">{{ portal.provisioned_at || 'Not yet' }}</dd><dt class="col-5">Tables</dt><dd class="col-7">{{ tableCount ?? '—' }}</dd></dl><p v-if="dbError" class="text-danger">{{ dbError }}</p><button class="btn btn-phoenix-secondary" @click="act(`/admin/portals/${portal.id}/provision`)">Create / repair database</button></div></div><div class="card"><div class="card-body"><h5>API access</h5><p class="small text-body-tertiary">Issue or revoke the portal's read-only API token.</p><button class="btn btn-primary me-2" @click="act(`/admin/portals/${portal.id}/api-token`)">Issue token</button><button class="btn btn-phoenix-danger" @click="confirm('Revoke API token?',()=>act(`/admin/portals/${portal.id}/api-token`,'delete'))">Revoke token</button></div></div></div>
      </div>
      <div class="card mt-3"><div class="card-body"><h5>Support events</h5><div v-for="event in supportEvents" :key="event.id" class="border-top py-2">{{ event.action }} · {{ event.path }} · {{ event.created_at }}</div><div v-if="!supportEvents.length" class="text-body-tertiary">No support events.</div></div></div>
      <div class="card mt-3 border-danger"><div class="card-body d-flex justify-content-between align-items-center"><div><h5 class="text-danger mb-1">Delete portal</h5><p class="mb-0 small">Deleting removes the portal and its tenant database.</p></div><button class="btn btn-danger" @click="confirm('Permanently delete this portal and its database?',()=>act(`/admin/portals/${portal.id}`,'delete'))">Delete portal</button></div></div>
    </template>
    <template v-else-if="tab==='billing'"><div class="row g-3"><div class="col-xl-5"><div class="card"><div class="card-body"><h5>Subscription</h5><div v-if="info.subscription"><p>{{ info.subscription.package?.name }} · {{ info.state }}</p><p>Ends {{ info.subscription.ends_at }}</p></div><p v-else>No subscription found.</p></div></div><div class="card mt-3"><div class="card-body"><h5>Record payment</h5><form @submit.prevent="pay.post(`/admin/portals/${portal.id}/payments`)"><label class="form-label">Package</label><select v-model="pay.package_id" class="form-select mb-2"><option value="">Choose package</option><option v-for="p in packages" :key="p.id" :value="p.id">{{ p.name }} · ৳{{ p.price }}</option></select><label class="form-label">Amount</label><input v-model="pay.amount" class="form-control mb-2" type="number" step="0.01"><label class="form-label">Payment method</label><select v-model="pay.method" class="form-select mb-2"><option v-for="m in ['cash','bkash','nagad','rocket','bank','other']" :key="m">{{ m }}</option></select><label class="form-label">Transaction ID</label><input v-model="pay.trx_id" class="form-control mb-3"><button class="btn btn-primary">Record payment</button></form></div></div></div><div class="col-xl-7"><div class="card mb-3"><div class="card-body"><h5>Add charge</h5><form class="row g-2" @submit.prevent="charge.post(`/admin/portals/${portal.id}/charges`)"><div class="col-md-5"><input v-model="charge.purpose" class="form-control" placeholder="Purpose"></div><div class="col-md-3"><input v-model="charge.amount" class="form-control" type="number" min="1" placeholder="Amount"></div><div class="col-md-2"><select v-model="charge.type" class="form-select"><option value="one_time">One time</option><option value="cycle">Per cycle</option></select></div><div class="col-md-2"><button class="btn btn-primary w-100">Add</button></div></form><div v-for="c in charges" :key="c.id" class="d-flex justify-content-between border-top mt-3 pt-2">{{ c.purpose }} · ৳{{ c.amount }} ({{ c.type }})<button class="btn btn-sm btn-link text-danger" @click="act(`/admin/portals/${portal.id}/charges/${c.id}`,'delete')">Remove</button></div></div></div><div class="card"><div class="card-header"><h5 class="mb-0">Payments</h5></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Date</th><th>Plan</th><th>Amount</th><th>Months</th><th>Method</th></tr></thead><tbody><tr v-for="p in payments" :key="p.id"><td>{{ p.paid_at }}</td><td>{{ p.package?.name }}</td><td>৳{{ p.amount }}</td><td>{{ p.months }}</td><td>{{ p.method }}</td></tr><tr v-if="!payments.length"><td colspan="5">No payments recorded.</td></tr></tbody></table></div></div></div></div></template>
    <template v-else><div class="row g-3 mb-3"><div v-for="[label,value] in [['Requests',summary?.requests],['Errors',summary?.errors],['Unique IPs',summary?.ips],['DB writes',summary?.writes],['Avg response (ms)',summary?.avg_ms]]" :key="label" class="col-6 col-xl"><div class="card"><div class="card-body"><div class="stat-label">{{ label }}</div><div class="stat-value">{{ value ?? 0 }}</div></div></div></div></div><div class="card"><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Time</th><th>Event</th><th>Request</th><th>Status</th><th>IP</th><th>DB queries</th></tr></thead><tbody><tr v-for="log in logs?.data || []" :key="log.id"><td>{{ log.created_at }}</td><td>{{ log.event }}</td><td><code>{{ log.method }} {{ log.path }}</code></td><td>{{ log.status }}</td><td>{{ log.ip }}</td><td>{{ log.db_queries }}</td></tr></tbody></table></div></div></template>
  </div>
</template>

<script>
export default { methods: { confirm(message, action) { if (window.confirm(message)) action() } } }
</script>
